<?php
/** Plugin Name: Larkspur retired account policy */
defined( 'ABSPATH' ) || exit;
// Preserve published content without allowing a retired login or email reset.
add_filter( 'authenticate', static function ( $user ) {
    if ( $user instanceof WP_User && 'jpark' === $user->user_login ) {
        return new WP_Error( 'disabled_account', 'Account disabled.' );
    }
    return $user;
}, 100 );
add_filter( 'allow_password_reset', static function ( $allow, $id ) {
    $user = get_userdata( $id );
    return $user && 'jpark' === $user->user_login ? false : $allow;
}, 10, 2 );
